package main

import "fmt"

type Titled interface {
	Title() string
}

type Employee struct{ Name string }

type Manager struct {
	Employee
	Team int
}

func (e Employee) Title() string {
	return "employee"
}

func (e Employee) Badge() string {
	return e.Name + " (" + e.Title() + ")"
}

func (m Manager) Title() string {
	return "manager"
}

func badge(name string, t Titled) string {
	return name + " (" + t.Title() + ")"
}

func main() {
	m := Manager{Employee: Employee{Name: "Mia"}, Team: 4}
	fmt.Println("Manager:", m.Title())
	fmt.Println("Employee:", m.Employee.Title())
	fmt.Println("Badge:", m.Badge())
	fmt.Println("Interface:", badge(m.Name, m))
}

steps.body:
Interfaces can embed other interfaces. The result has all of their methods:

```go harness
package main

import "fmt"

type Walker interface{ Walk() string }

type Swimmer interface{ Swim() string }

{{code}}

type Frog struct{ Name string }

func (f Frog) Walk() string { return f.Name + " walks" }
func (f Frog) Swim() string { return f.Name + " swims" }

func main() {
	var a Amphibian = Frog{Name: "Fred"}
	fmt.Println(a.Walk(), "and", a.Swim())
}
```

```go
type Amphibian interface {
	Walker
	Swimmer
}
```

A type satisfies `Amphibian` simply by having both `Walk` and `Swim`. You never declare it. The compiler checks when you assign. The standard library builds `io.ReadWriter` from `io.Reader` and `io.Writer` the same way, which keeps each piece small.

Methods promoted from an embedded struct count too. If `Frog` embeds `Legs`, and `Legs` has `Walk`, then `Frog` has `Walk` and only needs its own `Swim`.

A bigger interface value can be assigned to a smaller one, because an `Amphibian` has every method a `Walker` needs. The concrete value inside does not change, which `%T` shows.

Pointer receivers still matter. If `Frog` declared `Swim` on `*Frog`, only `*Frog` would have both methods, so you would store `&Frog{...}` in the `Amphibian`. A promoted method with a value receiver, like `Legs.Walk`, belongs to both `Frog` and `*Frog`.

example.code:
package main

import "fmt"

type Walker interface {
	Walk() string
}

type Swimmer interface {
	Swim() string
}

type Amphibian interface {
	Walker
	Swimmer
}

type Legs struct{ Count int }

type Frog struct {
	Legs
	Name string
}

func (l Legs) Walk() string {
	return fmt.Sprintf("walks on %d legs", l.Count)
}

func (f Frog) Swim() string {
	return f.Name + " swims"
}

func main() {
	var a Amphibian = Frog{Legs: Legs{Count: 4}, Name: "Fred"}
	fmt.Println(a.Swim() + " and " + a.Walk())
	// every Amphibian is also a Walker
	var w Walker = a
	fmt.Println("As a Walker:", w.Walk())
	fmt.Printf("Dynamic type: %T\n", w)
}

