practice.solution:
package main

import "fmt"

type Saver interface {
	Save(key, value string)
}

type Loader interface {
	Load(key string) (string, bool)
}

type Store interface {
	Saver
	Loader
}

type Cache struct {
	data map[string]string
}

type MemoryStore struct {
	Cache
}

func (c Cache) Load(key string) (string, bool) {
	v, ok := c.data[key]
	return v, ok
}

func (m *MemoryStore) Save(key, value string) {
	m.data[key] = value
}

func main() {
	var s Store = &MemoryStore{Cache: Cache{data: map[string]string{}}}
	s.Save("theme", "dark")
	s.Save("lang", "go")
	var l Loader = s
	for _, key := range []string{"theme", "font"} {
		if v, ok := l.Load(key); ok {
			fmt.Printf("%s: %s\n", key, v)
		} else {
			fmt.Printf("%s: missing\n", key)
		}
	}
	fmt.Printf("Dynamic type: %T\n", l)
}

steps.body:
A type assertion checks one type. A **type switch** checks several in one go:

```go harness
package main

import "fmt"

func measure(x interface{}) int {
	{{code}}
	return 0
}

func main() {
	fmt.Println(measure(21), measure("gopher"), measure(true))
}
```

```go
switch v := x.(type) {
case int:
	return v * 2
case string:
	return len(v)
}
```

`x.(type)` only works in a switch, and `x` must be an interface value. Inside each case, `v` has that case's type, so `v * 2` is int math and `len(v)` counts bytes, with no extra assertion.

- A case with several types, such as `case float32, float64:` (`float32` is the 32-bit float), leaves `v` as `interface{}`, so you can print it but not do math with it.
- `case nil` matches only an interface holding nothing. A nil `*MyError` stored in an interface is not nil, so it lands in `case error`.
- `default` catches every other type, and `%T` names it.
- An interface type works as a case: `case error` matches any value with an `Error() string` method.

Cases are tried from top to bottom and the first match wins, so put specific types before broad interface cases. Remember that untyped constants get their default type when stored: `'x'` is an `int32`, `2.5` is a `float64`.

example.code:
package main

import (
	"errors"
	"fmt"
)

func describe(x interface{}) string {
	switch v := x.(type) {
	case int:
		return fmt.Sprintf("int %d, doubled %d", v, v*2)
	case string:
		return fmt.Sprintf("string %q with %d bytes", v, len(v))
	case bool:
		return fmt.Sprintf("bool %t, negated %t", v, !v)
	case []int:
		return fmt.Sprintf("slice of %d ints", len(v))
	case float32, float64:
		// two types in one case, so v is still interface{}
		return fmt.Sprintf("float %v", v)
	case error:
		return "error: " + v.Error()
	case nil:
		return "nil"
	default:
		return fmt.Sprintf("other %T", v)
	}
}

func main() {
	values := []interface{}{42, "gopher", true, []int{1, 2, 3}, errors.New("disk full"), nil, 2.5, 'x'}
	for _, x := range values {
		fmt.Println(describe(x))
	}
}

