package main

import "fmt"

func render(x interface{}) string {
	switch v := x.(type) {
	case float64:
		return fmt.Sprintf("%.1f", v)
	case string:
		return fmt.Sprintf("%q", v)
	case bool:
		return fmt.Sprintf("%t", v)
	case nil:
		return "null"
	case []interface{}:
		return fmt.Sprintf("list of %d", len(v))
	default:
		return "unknown"
	}
}

func main() {
	values := []interface{}{3.0, "hi", false, nil, []interface{}{1.0, "a", true}, 3.14, 7}
	for _, x := range values {
		fmt.Println(render(x))
	}
}
